import{_ as a,C as r,o as i,c as n,j as o,a as d,E as s,a4 as l}from"./chunks/framework.3ld2D-Uy.js";const w=JSON.parse(`{"title":"Free Online Video Cropper, Trimmer, and Resizer","description":"Crop, trim, and resize MP4, WebM, MOV, and AVI videos to a new duration, aspect ratio, or exact resolution. Export a private, browser-processed WebM video.","frontmatter":{"title":"Free Online Video Cropper, Trimmer, and Resizer","description":"Crop, trim, and resize MP4, WebM, MOV, and AVI videos to a new duration, aspect ratio, or exact resolution. Export a private, browser-processed WebM video.","pageClass":"crop-tool-layout","permalink":"/cropvideo/","canonicalUrl":"https://curvednebula.com/cropvideo/","meta":[{"name":"keywords","content":"crop video online, trim video online, resize video online, AVI video cropper, crop AVI video, change video aspect ratio, video resolution converter, WebCodecs video editor, crop video to 9:16, crop video to 16:9"},{"property":"og:title","content":"Free Online Video Cropper, Trimmer, and Resizer"},{"property":"og:description","content":"Crop, trim, and resize videos, then save as WebM. Private, local, and powered by WebCodecs."},{"property":"og:type","content":"website"},{"property":"og:url","content":"https://curvednebula.com/cropvideo/"},{"name":"twitter:card","content":"summary"},{"name":"twitter:title","content":"Free Online Video Cropper, Trimmer, and Resizer"},{"name":"twitter:description","content":"Change a video's duration, crop, aspect ratio, and resolution privately in your browser."}],"aside":false},"headers":[],"relativePath":"cropvideo/index.md","filePath":"cropvideo/README.md"}`),c={name:"cropvideo/index.md"};function p(h,e,m,u,v,b){const t=r("VideoCropper");return i(),n("div",null,[e[0]||(e[0]=o("h1",{id:"crop-trim-and-resize-videos-online",tabindex:"-1"},[d("Crop, Trim, and Resize Videos Online "),o("a",{class:"header-anchor",href:"#crop-trim-and-resize-videos-online","aria-label":'Permalink to "Crop, Trim, and Resize Videos Online"'},"​")],-1)),s(t),e[1]||(e[1]=l('<h2 id="about" tabindex="-1">About <a class="header-anchor" href="#about" aria-label="Permalink to &quot;About&quot;">​</a></h2><p>Crop a video to a custom area or a common aspect ratio, trim unwanted time from the beginning or end, resize it to an exact output resolution, and save the result as a WebM file. MP4, WebM, MOV, and AVI files are supported. Processing happens locally in your browser—your video is never uploaded.</p><h2 id="how-to-crop-a-video" tabindex="-1">How to crop a video <a class="header-anchor" href="#how-to-crop-a-video" aria-label="Permalink to &quot;How to crop a video&quot;">​</a></h2><ol><li>Select a video from your device or drag and drop it into the cropper.</li><li>Drag inside the crop area to reposition it, then drag the handles to resize it.</li><li>Drag the trim handles to select the part of the video to keep, or set either boundary to the playhead.</li><li>Choose an aspect ratio such as 16:9, 1:1, 4:5, or 9:16.</li><li>Keep the crop resolution, choose a long-edge preset, or enter a custom width and height.</li><li>Select a frame rate and quality level, then choose <strong>Save Video</strong>.</li></ol><p>The editor previews only the selected time range with the same crop. Exported dimensions are kept even for broad WebM codec compatibility.</p><h2 id="common-video-aspect-ratios" tabindex="-1">Common video aspect ratios <a class="header-anchor" href="#common-video-aspect-ratios" aria-label="Permalink to &quot;Common video aspect ratios&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Aspect ratio</th><th>Typical use</th></tr></thead><tbody><tr><td>16:9</td><td>YouTube, presentations, and landscape video</td></tr><tr><td>9:16</td><td>Reels, Shorts, Stories, and vertical mobile video</td></tr><tr><td>1:1</td><td>Square social posts</td></tr><tr><td>4:5</td><td>Portrait feed posts</td></tr><tr><td>4:3</td><td>Classic video and presentations</td></tr><tr><td>2.35:1</td><td>Cinematic widescreen</td></tr></tbody></table><h2 id="private-webcodecs-video-processing" tabindex="-1">Private WebCodecs video processing <a class="header-anchor" href="#private-webcodecs-video-processing" aria-label="Permalink to &quot;Private WebCodecs video processing&quot;">​</a></h2><p>The source file stays on your device. Frames are cropped and resized in the browser, encoded with the browser&#39;s WebCodecs implementation, and packaged into a downloadable WebM file. No account, watermark, or server upload is involved.</p><p>Audio is preserved as Opus when your browser can decode the source audio track and supports WebCodecs audio encoding. If it cannot, the tool still exports the cropped video without audio and tells you after export.</p><h3 id="avi-support" tabindex="-1">AVI support <a class="header-anchor" href="#avi-support" aria-label="Permalink to &quot;AVI support&quot;">​</a></h3><p>Browsers cannot reliably preview AVI containers directly, so the tool uses a small demuxer hosted with this site to read AVI packets and sends them to WebCodecs one frame at a time. It does not convert the entire source into a temporary in-memory video, so large AVI files do not need to fit inside a WebAssembly heap. Motion JPEG AVI has a dedicated local decoder path.</p><p>AVI is a container and can hold many video codecs. The tool supports AVI video tracks that the browser&#39;s WebCodecs implementation can decode, plus Motion JPEG. It reports the codec name when an AVI uses an unsupported codec. AVI exports currently omit the source audio track.</p><h2 id="browser-compatibility" tabindex="-1">Browser compatibility <a class="header-anchor" href="#browser-compatibility" aria-label="Permalink to &quot;Browser compatibility&quot;">​</a></h2><p>Video export requires a browser with the WebCodecs <code>VideoEncoder</code> API. Recent Chromium-based browsers such as Chrome and Edge offer the broadest support. The tool selects VP9 when available and falls back to VP8.</p><h2 id="frequently-asked-questions" tabindex="-1">Frequently asked questions <a class="header-anchor" href="#frequently-asked-questions" aria-label="Permalink to &quot;Frequently asked questions&quot;">​</a></h2><h3 id="can-i-remove-time-from-the-beginning-or-end" tabindex="-1">Can I remove time from the beginning or end? <a class="header-anchor" href="#can-i-remove-time-from-the-beginning-or-end" aria-label="Permalink to &quot;Can I remove time from the beginning or end?&quot;">​</a></h3><p>Yes. Move the start and end trim handles, enter exact times in seconds, or move the playhead and choose <strong>Set to playhead</strong>. Preview playback stays inside the selected range, and the exported video starts at time zero.</p><h3 id="can-i-crop-a-landscape-video-into-a-vertical-video" tabindex="-1">Can I crop a landscape video into a vertical video? <a class="header-anchor" href="#can-i-crop-a-landscape-video-into-a-vertical-video" aria-label="Permalink to &quot;Can I crop a landscape video into a vertical video?&quot;">​</a></h3><p>Yes. Choose <strong>Vertical · 9:16</strong>, move the selection over the important part of the frame, and select a suitable output resolution such as a 1080-pixel long edge.</p><h3 id="can-i-enter-an-exact-video-resolution" tabindex="-1">Can I enter an exact video resolution? <a class="header-anchor" href="#can-i-enter-an-exact-video-resolution" aria-label="Permalink to &quot;Can I enter an exact video resolution?&quot;">​</a></h3><p>Yes. Choose <strong>Custom</strong> under Output resolution, then enter the width and height. Keep the aspect ratio option enabled to avoid stretching.</p><h3 id="what-format-does-the-tool-export" tabindex="-1">What format does the tool export? <a class="header-anchor" href="#what-format-does-the-tool-export" aria-label="Permalink to &quot;What format does the tool export?&quot;">​</a></h3><p>The tool exports a WebM file encoded with VP9 or VP8. Audio is encoded as Opus when it can be preserved.</p><h3 id="can-i-crop-an-avi-video" tabindex="-1">Can I crop an AVI video? <a class="header-anchor" href="#can-i-crop-an-avi-video" aria-label="Permalink to &quot;Can I crop an AVI video?&quot;">​</a></h3><p>Yes. Select the <code>.avi</code> file normally. The browser reads it incrementally and opens it in the same crop editor without first creating a full temporary copy. Compatibility depends on the video codec stored inside the AVI container.</p><h3 id="why-can-video-export-take-a-while" tabindex="-1">Why can video export take a while? <a class="header-anchor" href="#why-can-video-export-take-a-while" aria-label="Permalink to &quot;Why can video export take a while?&quot;">​</a></h3><p>Every frame must be decoded, cropped, resized, and encoded on your device. Longer videos, higher resolutions, and 60 fps exports require more processing.</p><h3 id="is-there-a-file-size-limit" tabindex="-1">Is there a file-size limit? <a class="header-anchor" href="#is-there-a-file-size-limit" aria-label="Permalink to &quot;Is there a file-size limit?&quot;">​</a></h3><p>The tool does not impose an upload limit because the video is not uploaded. AVI input is read incrementally. When Chrome or Edge offers a save-file dialog, output is also written progressively to disk; the download fallback must hold the completed output in browser memory. Available storage, video duration, resolution, and device performance still set practical limits.</p>',30))])}const y=a(c,[["render",p]]);export{w as __pageData,y as default};
